package com.simibubi.create.test;

import com.simibubi.create.*;
import com.simibubi.create.api.contraption.BlockMovementChecks;
import com.simibubi.create.content.contraptions.*;
import com.simibubi.create.content.contraptions.bearing.BearingContraption;
import com.simibubi.create.content.contraptions.chassis.*;
import net.fabricmc.fabric.api.event.player.UseBlockCallback;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.network.chat.Component;
import net.minecraft.util.ProblemReporter;
import net.minecraft.world.*;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.*;
import net.minecraft.world.item.context.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.BarrelBlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.level.storage.*;
import net.minecraft.world.phys.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;

/** Structural outcomes through native state, group search, settings and actual ownership transfer. */
public class ChassisGameTests {
    private static final BlockPos P=new BlockPos(4,5,4);
    private static BlockState linear(Direction.Axis axis){return AllBlocks.LINEAR_CHASSIS.defaultBlockState().setValue(AbstractChassisBlock.AXIS,axis);}
    private static BlockState sticky(BlockState state,Direction side){return state.setValue(((AbstractChassisBlock)state.getBlock()).getGlueableSide(state,side),true);}
    private static ChassisBlockEntity place(GameTestHelper h,BlockPos pos,BlockState state,int range){h.setBlock(pos,state);var chassis=(ChassisBlockEntity)h.getLevel().getBlockEntity(h.absolutePos(pos));chassis.setRange(range);return chassis;}
    private static BlockState state(GameTestHelper h,BlockPos pos){return h.getLevel().getBlockState(h.absolutePos(pos));}
    private static Set<BlockPos> selection(ChassisBlockEntity chassis,Direction forced)throws Exception{return new HashSet<>(chassis.getIncludedBlockPositions(forced,false));}
    private static void line(GameTestHelper h,Direction direction,int count){for(int i=1;i<=count;i++)h.setBlock(P.relative(direction,i),Blocks.STONE);}
    private static Player facing(GameTestHelper h,BlockPos pos){var player=h.makeMockPlayer(GameType.SURVIVAL);var center=Vec3.atCenterOf(h.absolutePos(pos));player.setPos(center.x,center.y-player.getEyeHeight(),center.z+3);player.setYRot(180);player.setYHeadRot(180);player.setXRot(0);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AllItems.WRENCH));return player;}
    private static InteractionResult use(GameTestHelper h,Player player,BlockPos pos,Direction side){
        var actual=h.absolutePos(pos);var hit=new BlockHitResult(Vec3.atCenterOf(actual).add(side.getUnitVec3().scale(.5)),side,actual,false);
        var event=UseBlockCallback.EVENT.invoker().interact(player,h.getLevel(),InteractionHand.MAIN_HAND,hit);if(event!=InteractionResult.PASS)return event;
        return state(h,pos).useItemOn(player.getMainHandItem(),h.getLevel(),player,InteractionHand.MAIN_HAND,hit);
    }
    @GameTest public void registeredMovementCheckOverridesChassisFallbackInReverseOrder(GameTestHelper h){
        var active=new AtomicBoolean(true);var block=linear(Direction.Axis.X);var actual=h.absolutePos(P);
        BlockMovementChecks.registerMovementAllowedCheck((s,l,p)->active.get()&&l==h.getLevel()&&p.equals(actual)&&s==block?BlockMovementChecks.CheckResult.SUCCESS:BlockMovementChecks.CheckResult.PASS);
        BlockMovementChecks.registerMovementAllowedCheck((s,l,p)->active.get()&&l==h.getLevel()&&p.equals(actual)&&s==block?BlockMovementChecks.CheckResult.FAIL:BlockMovementChecks.CheckResult.PASS);
        try{h.assertFalse(BlockMovementChecks.isMovementAllowed(block,h.getLevel(),actual),"Last registered refusal wins before the chassis allow fallback");}finally{active.set(false);}
        h.assertTrue(BlockMovementChecks.isMovementAllowed(block,h.getLevel(),actual),"PASS callbacks restore the native chassis fallback");h.succeed();
    }
    @GameTest public void sourceDefaultsAndFlatRangeNbtSurviveLoadBeforeSetLevel(GameTestHelper h){
        var chassis=place(h,P,linear(Direction.Axis.Y),7);var tag=chassis.saveWithFullMetadata(h.getLevel().registryAccess());h.assertValueEqual(tag.getIntOr("ScrollValue",0),7,"Flat source range field");var copy=new ChassisBlockEntity(h.absolutePos(P),state(h,P));copy.loadWithComponents(TagValueInput.create(ProblemReporter.DISCARDING,h.getLevel().registryAccess(),tag));copy.setLevel(h.getLevel());h.assertTrue(copy.getRange()==7&&copy.currentlySelectedRange==7,"Native initial load preserves source range");h.succeed();
    }
    @GameTest public void nativeSlimeUseCostsNoItemAndSecondClickSetsBothEnds(GameTestHelper h){
        place(h,P,linear(Direction.Axis.X),3);var player=facing(h,P);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.SLIME_BALL,3));h.assertTrue(use(h,player,P,Direction.EAST).consumesAction(),"First native face use");h.assertTrue(state(h,P).getValue(LinearChassisBlock.STICKY_TOP)&&!state(h,P).getValue(LinearChassisBlock.STICKY_BOTTOM),"Only clicked end first");use(h,player,P,Direction.EAST);h.assertTrue(state(h,P).getValue(LinearChassisBlock.STICKY_TOP)&&state(h,P).getValue(LinearChassisBlock.STICKY_BOTTOM)&&player.getMainHandItem().getCount()==3,"Repeated same-face use fills opposite end without inventory cost");h.succeed();
    }
    @GameTest public void actualSuperGlueCallbackPassesStickyFaceWithoutStartingAreaSelection(GameTestHelper h){
        place(h,P,linear(Direction.Axis.Z),3);var player=facing(h,P);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AllItems.SUPER_GLUE));int damage=player.getMainHandItem().getDamageValue();h.assertTrue(use(h,player,P,Direction.SOUTH).consumesAction()&&state(h,P).getValue(LinearChassisBlock.STICKY_TOP)&&player.getMainHandItem().getDamageValue()==damage,"Registered Super Glue callback permits real chassis face handling without durability cost");h.succeed();
    }
    @GameTest public void emptyHandSneakRemovesOnlyClickedGlue(GameTestHelper h){
        place(h,P,sticky(sticky(linear(Direction.Axis.X),Direction.EAST),Direction.WEST),3);var player=facing(h,P);player.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);player.setShiftKeyDown(true);h.assertTrue(use(h,player,P,Direction.EAST).consumesAction()&&!state(h,P).getValue(LinearChassisBlock.STICKY_TOP)&&state(h,P).getValue(LinearChassisBlock.STICKY_BOTTOM),"Only clicked glue flag is removed");h.succeed();
    }
    @GameTest public void sameKindAlignedNeighborClearsAndBlocksInternalGlue(GameTestHelper h){
        place(h,P,sticky(linear(Direction.Axis.X),Direction.EAST),3);place(h,P.east(),linear(Direction.Axis.X),3);h.assertFalse(state(h,P).getValue(LinearChassisBlock.STICKY_TOP),"Internal end clears through native shape update");var player=facing(h,P);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.SLIME_BALL));use(h,player,P,Direction.EAST);h.assertFalse(state(h,P).getValue(LinearChassisBlock.STICKY_TOP),"Cannot reglue same-kind internal end");h.succeed();
    }
    @GameTest public void mixedKindNeighborKeepsIndependentEndGlue(GameTestHelper h){place(h,P,sticky(linear(Direction.Axis.X),Direction.EAST),3);place(h,P.east(),AllBlocks.SECONDARY_LINEAR_CHASSIS.defaultBlockState().setValue(AbstractChassisBlock.AXIS,Direction.Axis.X),3);h.assertTrue(state(h,P).getValue(LinearChassisBlock.STICKY_TOP),"Distinct variants do not suppress end glue");h.succeed();}
    @GameTest public void perpendicularNeighborKeepsIndependentEndGlue(GameTestHelper h){place(h,P,sticky(linear(Direction.Axis.X),Direction.EAST),3);place(h,P.east(),linear(Direction.Axis.Y),3);h.assertTrue(state(h,P).getValue(LinearChassisBlock.STICKY_TOP),"Distinct axes do not suppress end glue");h.succeed();}
    @GameTest public void placementCopiesEitherLinearVariantUnlessSneaking(GameTestHelper h){
        place(h,P.below(),AllBlocks.SECONDARY_LINEAR_CHASSIS.defaultBlockState().setValue(AbstractChassisBlock.AXIS,Direction.Axis.X),3);var player=facing(h,P);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AllBlocks.LINEAR_CHASSIS));var actual=h.absolutePos(P.below());var input=new BlockPlaceContext(new UseOnContext(player,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(actual).add(0,.5,0),Direction.UP,actual,false)));h.assertValueEqual(AllBlocks.LINEAR_CHASSIS.getStateForPlacement(input).getValue(AbstractChassisBlock.AXIS),Direction.Axis.X,"Neighbor variant supplies axis");player.setShiftKeyDown(true);h.assertValueEqual(AllBlocks.LINEAR_CHASSIS.getStateForPlacement(input).getValue(AbstractChassisBlock.AXIS),Direction.Axis.Y,"Sneak uses clicked pillar axis");h.succeed();
    }
    @GameTest public void nonStickyLinearRequiresActualForcedMovement(GameTestHelper h)throws Exception{var chassis=place(h,P,linear(Direction.Axis.X),3);line(h,Direction.EAST,3);line(h,Direction.WEST,3);h.assertTrue(selection(chassis,null).isEmpty(),"A bearing does not invent sticky range");var pushed=selection(chassis,Direction.EAST);h.assertTrue(pushed.size()==3&&pushed.contains(h.absolutePos(P.east(3)))&&!pushed.contains(h.absolutePos(P.west())),"Actual forced direction pushes only its outward range");h.succeed();}
    @GameTest public void twoStickyEndsHonorExactOwnRange(GameTestHelper h)throws Exception{var chassis=place(h,P,sticky(sticky(linear(Direction.Axis.X),Direction.EAST),Direction.WEST),2);line(h,Direction.EAST,3);line(h,Direction.WEST,3);var selected=selection(chassis,null);h.assertTrue(selected.size()==4&&selected.contains(h.absolutePos(P.east(2)))&&selected.contains(h.absolutePos(P.west(2)))&&!selected.contains(h.absolutePos(P.east(3))),"Two real sticky ends stop at configured range");h.succeed();}
    @GameTest public void brittleBlockStopsBeforeInclusion(GameTestHelper h)throws Exception{var chassis=place(h,P,sticky(linear(Direction.Axis.X),Direction.EAST),5);h.setBlock(P.east(),Blocks.STONE);h.setBlock(P.east(2).below(),Blocks.STONE);h.setBlock(P.east(2),Blocks.TORCH);h.setBlock(P.east(3),Blocks.STONE);h.assertValueEqual(selection(chassis,null),Set.of(h.absolutePos(P.east())),"Brittle target and blocks behind it are excluded");h.succeed();}
    @GameTest public void gapStopsLinearSelectionBeforeDisconnectedIsland(GameTestHelper h)throws Exception{var chassis=place(h,P,sticky(linear(Direction.Axis.X),Direction.EAST),5);h.setBlock(P.east(),Blocks.STONE);h.setBlock(P.east(3),Blocks.STONE);h.assertValueEqual(selection(chassis,null),Set.of(h.absolutePos(P.east())),"Air stops the line");h.succeed();}
    @GameTest public void nonsupportiveTerminalIsIncludedButCannotTransmitRange(GameTestHelper h)throws Exception{var chassis=place(h,P,sticky(linear(Direction.Axis.X),Direction.EAST),5);h.setBlock(P.east(),Blocks.STONE);h.setBlock(P.east(2),AllBlocks.MECHANICAL_DRILL.defaultBlockState().setValue(BlockStateProperties.FACING,Direction.EAST));h.setBlock(P.east(3),Blocks.STONE);h.assertValueEqual(selection(chassis,null),Set.of(h.absolutePos(P.east()),h.absolutePos(P.east(2))),"Drill body moves but front does not transmit range");h.succeed();}
    @GameTest public void linearGroupsSeparateVariantsAndAxes(GameTestHelper h)throws Exception{var chassis=place(h,P,linear(Direction.Axis.Y),1);place(h,P.east(),linear(Direction.Axis.Y),3);place(h,P.west(),AllBlocks.SECONDARY_LINEAR_CHASSIS.defaultBlockState(),3);place(h,P.north(),linear(Direction.Axis.X),3);h.assertValueEqual(chassis.collectChassisGroup().size(),2,"Only same-kind parallel linear members are grouped");h.succeed();}
    @GameTest public void radialGroupsFollowOnlyPillarAxis(GameTestHelper h)throws Exception{var radial=AllBlocks.RADIAL_CHASSIS.defaultBlockState().setValue(AbstractChassisBlock.AXIS,Direction.Axis.Y);var chassis=place(h,P,radial,2);place(h,P.above(),radial,2);place(h,P.east(),radial,2);h.assertValueEqual(chassis.collectChassisGroup().size(),2,"Radial chain ignores side-adjacent chassis");h.succeed();}
    @GameTest public void radialFloodCanReachAroundButStaysInItsOwnPlane(GameTestHelper h)throws Exception{var radial=sticky(AllBlocks.RADIAL_CHASSIS.defaultBlockState().setValue(AbstractChassisBlock.AXIS,Direction.Axis.Y),Direction.NORTH);var chassis=place(h,P,radial,2);for(var pos:List.of(P.north(),P.north().east(),P.east(),P.north().above()))h.setBlock(pos,Blocks.STONE);var selected=selection(chassis,null);h.assertTrue(selected.size()==3&&selected.contains(h.absolutePos(P.east()))&&!selected.contains(h.absolutePos(P.north().above())),"Connected planar path can go around the origin without spilling along axis");h.succeed();}
    @GameTest public void radialFloodUsesEuclideanRadius(GameTestHelper h)throws Exception{var chassis=place(h,P,sticky(AllBlocks.RADIAL_CHASSIS.defaultBlockState(),Direction.EAST),2);for(var pos:List.of(P.east(),P.east(2),P.east(2).south(),P.east(2).south(2)))h.setBlock(pos,Blocks.STONE);var selected=selection(chassis,null);h.assertTrue(selected.size()==3&&selected.contains(h.absolutePos(P.east(2).south()))&&!selected.contains(h.absolutePos(P.east(2).south(2))),"sqrt(5) belongs to radius2.5; sqrt(8) does not");h.succeed();}
    @GameTest public void radialFloodCannotCrossAirToDisconnectedSide(GameTestHelper h)throws Exception{var chassis=place(h,P,sticky(AllBlocks.RADIAL_CHASSIS.defaultBlockState(),Direction.NORTH),3);h.setBlock(P.north(),Blocks.STONE);h.setBlock(P.east(),Blocks.STONE);h.assertValueEqual(selection(chassis,null),Set.of(h.absolutePos(P.north())),"Revisiting origin cannot activate an unglued side");h.succeed();}
    @GameTest public void radialMultipleStickySearchesDoNotDuplicateSelection(GameTestHelper h)throws Exception{var radial=sticky(sticky(AllBlocks.RADIAL_CHASSIS.defaultBlockState(),Direction.NORTH),Direction.EAST);var chassis=place(h,P,radial,2);for(var pos:List.of(P.north(),P.north().east(),P.east()))h.setBlock(pos,Blocks.STONE);h.assertValueEqual(chassis.getIncludedBlockPositions(null,false).size(),3,"Overlapping face floods yield one selected copy");h.succeed();}
    @GameTest public void previewRangeDoesNotMutateAuthoritativeAssemblyRange(GameTestHelper h)throws Exception{var chassis=place(h,P,sticky(linear(Direction.Axis.X),Direction.EAST),1);line(h,Direction.EAST,4);chassis.currentlySelectedRange=4;h.assertTrue(chassis.getIncludedBlockPositions(null,true).size()==4&&chassis.getIncludedBlockPositions(null,false).size()==1&&chassis.getRange()==1,"Client hover changes preview only");h.succeed();}
    @GameTest public void allAxisTransformsKeepTheActualStickyFace(GameTestHelper h){
        for(var block:List.of(AllBlocks.LINEAR_CHASSIS,AllBlocks.RADIAL_CHASSIS))for(var axis:Direction.Axis.values())for(var side:Direction.values()){
            var original=block.defaultBlockState().setValue(AbstractChassisBlock.AXIS,axis);var flag=block.getGlueableSide(original,side);if(flag==null)continue;original=original.setValue(flag,true);
            for(var transform:List.of(new StructureTransform(BlockPos.ZERO,90,0,0),new StructureTransform(BlockPos.ZERO,0,90,0),new StructureTransform(BlockPos.ZERO,0,0,90))){var rotated=transform.apply(original);var expected=transform.rotateFacing(side);for(var face:Direction.values()){var property=block.getGlueableSide(rotated,face);if(property!=null)h.assertTrue(rotated.getValue(property)==(face==expected),"Exactly the transformed physical face remains sticky");}}
            for(var mirror:List.of(Mirror.FRONT_BACK,Mirror.LEFT_RIGHT)){var mirrored=original.mirror(mirror);for(var face:Direction.values()){var property=block.getGlueableSide(mirrored,face);if(property!=null)h.assertTrue(mirrored.getValue(property)==(face==mirror.mirror(side)),"Mirroring retains exactly the reflected physical sticky face");}}
        }h.succeed();
    }
    @GameTest public void missingRangeAndGroupChunksAreRetryableAndNeverLoaded(GameTestHelper h){
        var far=new BlockPos(2000000,60,2000000);var chassis=new ChassisBlockEntity(far,sticky(linear(Direction.Axis.X),Direction.EAST));chassis.setLevel(h.getLevel());
        for(boolean group:new boolean[]{false,true}){boolean refused=false;try{if(group)chassis.collectChassisGroup();else chassis.getIncludedBlockPositions(null,false);}catch(AssemblyException unavailable){refused=unavailable.canRetry();}h.assertTrue(refused,"Unknown required cells refuse instead of returning partial success");}
        h.assertTrue(h.getLevel().getChunkSource().getChunkNow(far.getX()>>4,far.getZ()>>4)==null,"Neither scan loads a chunk");h.succeed();
    }
    @GameTest public void realSettingsValidateWrenchRangeAndActualPanelRay(GameTestHelper h){var chassis=place(h,P,linear(Direction.Axis.Y),2);var player=facing(h,P);h.assertTrue(ChassisSettings.apply(h.getLevel(),player,new ChassisSettings.SetRange(h.absolutePos(P),5,false))&&chassis.getRange()==5,"Valid real wrench/ray edits server range");player.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);h.assertFalse(ChassisSettings.apply(h.getLevel(),player,new ChassisSettings.SetRange(h.absolutePos(P),7,false)),"Missing wrench rejected");player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AllItems.WRENCH));h.assertFalse(ChassisSettings.apply(h.getLevel(),player,new ChassisSettings.SetRange(h.absolutePos(P),0,false)),"Invalid range rejected");h.setBlock(P.south(),Blocks.STONE);h.assertFalse(ChassisSettings.apply(h.getLevel(),player,new ChassisSettings.SetRange(h.absolutePos(P),7,false)),"Actual ray obstruction rejected");h.assertValueEqual(chassis.getRange(),5,"Rejected packets leave range intact");h.succeed();}
    @GameTest public void ctrlSettingsResolveOnlyTheActualConnectedGroup(GameTestHelper h){var first=place(h,P,linear(Direction.Axis.Y),2);var second=place(h,P.east(),linear(Direction.Axis.Y),3);var secondary=place(h,P.west(),AllBlocks.SECONDARY_LINEAR_CHASSIS.defaultBlockState(),4);h.assertTrue(ChassisSettings.apply(h.getLevel(),facing(h,P),new ChassisSettings.SetRange(h.absolutePos(P),6,true)),"Real Ctrl settings committed");h.assertTrue(first.getRange()==6&&second.getRange()==6&&secondary.getRange()==4,"Server resolves group instead of trusting client positions");h.succeed();}
    @GameTest public void actualGroupedCaptureSaveAndRestorePreserveRangesAndNamedCargo(GameTestHelper h)throws Exception{
        var first=place(h,P,sticky(linear(Direction.Axis.Y),Direction.UP),1);var second=place(h,P.east(),sticky(linear(Direction.Axis.Y),Direction.UP),2);h.setBlock(P.above(),Blocks.STONE);h.setBlock(P.east().above(),Blocks.BARREL);h.setBlock(P.east().above(2),Blocks.STONE);var cargo=new ItemStack(Items.DIAMOND,7);cargo.set(DataComponents.CUSTOM_NAME,Component.literal("Chassis cargo"));((BarrelBlockEntity)h.getLevel().getBlockEntity(h.absolutePos(P.east().above()))).setItem(0,cargo);
        var structure=new BearingContraption(false,Direction.UP);h.assertTrue(structure.assemble(h.getLevel(),h.absolutePos(P.below()))&&structure.getBlocks().size()==5,"Each actual group member contributes its own range");h.assertTrue(structure.tryRemoveBlocksFromWorld(h.getLevel(),BlockPos.ZERO),"Atomic ownership transfer");var saved=structure.writeNBT(h.getLevel().registryAccess(),false);var restored=Contraption.fromNBT(h.getLevel(),saved,false);var transform=new StructureTransform(h.absolutePos(P),0,90,0);h.assertTrue(restored.tryAddBlocksToWorld(h.getLevel(),transform),"Native saved structure restoration");
        h.assertTrue(((ChassisBlockEntity)h.getLevel().getBlockEntity(transform.apply(BlockPos.ZERO))).getRange()==1&&((ChassisBlockEntity)h.getLevel().getBlockEntity(transform.apply(new BlockPos(1,0,0)))).getRange()==2,"Own ranges survive real native NBT and rotation");var stack=((BarrelBlockEntity)h.getLevel().getBlockEntity(transform.apply(new BlockPos(1,1,0)))).getItem(0);h.assertTrue(stack.is(Items.DIAMOND)&&stack.getCount()==7&&stack.has(DataComponents.CUSTOM_NAME),"Owned cargo count/components remain exact");h.succeed();
    }
    @GameTest public void oversizedChassisSelectionLeavesAllSourceOwnershipIntact(GameTestHelper h)throws Exception{place(h,P,sticky(linear(Direction.Axis.X),Direction.EAST),2);line(h,Direction.EAST,2);int previous=ContraptionSettings.maxBlocksMoved;ContraptionSettings.maxBlocksMoved=1;var structure=new BearingContraption(false,Direction.UP);boolean failed=false;try{structure.assemble(h.getLevel(),h.absolutePos(P.below()));}catch(AssemblyException tooLarge){failed=true;}finally{ContraptionSettings.maxBlocksMoved=previous;}h.assertTrue(failed&&state(h,P).is(AllBlocks.LINEAR_CHASSIS)&&state(h,P.east(2)).is(Blocks.STONE)&&structure.getBlocks().isEmpty(),"No truncated carrier or partial removal at maxBlocksMoved");h.succeed();}
}
